CREATE TABLE IF NOT EXISTS migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, role_id TEXT NOT NULL REFERENCES roles(id));
CREATE TABLE roles(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE permissions(role_id TEXT REFERENCES roles(id), action TEXT NOT NULL, PRIMARY KEY(role_id,action));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE maximo_connections(id TEXT PRIMARY KEY, mode TEXT NOT NULL, base_url TEXT, auth_mode TEXT);
CREATE TABLE connector_capabilities(connection_id TEXT REFERENCES maximo_connections(id), discovered_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE sites(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,site_id TEXT NOT NULL REFERENCES sites(id));
CREATE TABLE buildings(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),name TEXT NOT NULL);
CREATE TABLE assets(id TEXT,site_id TEXT REFERENCES sites(id),location TEXT,PRIMARY KEY(id,site_id));
CREATE TABLE work_orders(id TEXT,site_id TEXT,project_id TEXT REFERENCES projects(id),status TEXT,external_revision TEXT,synced_at TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(id,site_id));
CREATE TABLE pm_records(id TEXT,site_id TEXT,project_id TEXT REFERENCES projects(id),status TEXT,external_revision TEXT,synced_at TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(id,site_id));
CREATE TABLE labor_resources(id TEXT PRIMARY KEY,name TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE labor_skills(labor_id TEXT REFERENCES labor_resources(id),skill TEXT,PRIMARY KEY(labor_id,skill));
CREATE TABLE shifts(id INTEGER PRIMARY KEY,name TEXT NOT NULL,start_hour INTEGER NOT NULL,hours INTEGER NOT NULL CHECK(hours>0 AND hours<=12));
CREATE TABLE resource_availability(id TEXT PRIMARY KEY,labor_id TEXT REFERENCES labor_resources(id),start_at TEXT,end_at TEXT);
CREATE TABLE schedule_rules(building TEXT PRIMARY KEY,minutes INTEGER NOT NULL CHECK(minutes>0),job_plan_precedence INTEGER NOT NULL DEFAULT 1);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE schedule_plans(id TEXT PRIMARY KEY,status TEXT NOT NULL,data TEXT NOT NULL,created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE schedule_items(id TEXT PRIMARY KEY,plan_id TEXT REFERENCES schedule_plans(id),record_id TEXT,site_id TEXT,start_at TEXT,finish_at TEXT,labor_id TEXT,data TEXT NOT NULL);
CREATE TABLE change_sets(id TEXT PRIMARY KEY,plan_id TEXT REFERENCES schedule_plans(id),snapshot_hash TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE change_requests(id TEXT PRIMARY KEY,change_set_id TEXT REFERENCES change_sets(id),record_id TEXT,site_id TEXT,record_type TEXT,data TEXT NOT NULL);
CREATE TABLE approvals(id TEXT PRIMARY KEY,change_set_id TEXT REFERENCES change_sets(id),snapshot_hash TEXT NOT NULL,approved_by TEXT REFERENCES users(id),approved_at TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE execution_jobs(id TEXT PRIMARY KEY,approval_id TEXT NOT NULL UNIQUE REFERENCES approvals(id),status TEXT NOT NULL,stop_requested INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,error TEXT);
CREATE TABLE execution_steps(id TEXT PRIMARY KEY,job_id TEXT REFERENCES execution_jobs(id),change_key TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL,result TEXT,UNIQUE(job_id,change_key));
CREATE TABLE audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,created_at TEXT NOT NULL,data TEXT NOT NULL,prev_hash TEXT NOT NULL,hash TEXT NOT NULL);
CREATE TABLE synchronization_runs(id TEXT PRIMARY KEY,status TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,records INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_work_orders_filters ON work_orders(project_id,status,site_id);
CREATE INDEX idx_jobs_status ON execution_jobs(status);
CREATE INDEX idx_audit_entity ON audit_events(entity,created_at);
